import Mathlib

open Set
open Topology

noncomputable section

variable {n : ℕ}

def ProdSet (f : (Fin n → ℝ) → ℝ) : Set ((Fin n → ℝ) × ℝ) :=
  {p | p.2 ≤ f p.1}

import Mathlib

open scoped BigOperators

variable {L : ℕ}

def coneProd (Y : Set (Fin L → ℝ)) : Set (Fin (L + 1) → ℝ) :=
  { y' | ∃ y ∈ Y, ∃ α : ℝ, 0 ≤ α ∧
    (∀ i : Fin L, y' (Fin.castSucc i) = α * y i) ∧
    y' (Fin.last L) = -α }

import Mathlib

/-- The transformation frontier: the set of boundary points {y ∈ ℝ^L | F(y) = 0}. -/
def transformationFrontier (L : ℕ) (F : (Fin L → ℝ) → ℝ) : Set (Fin L → ℝ) :=
  {y | F y = 0}

import Mathlib
open Topology

def IsQuasiconcave {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ q : ℝ, Convex ℝ {z : Fin n → ℝ | f z ≥ q}

import Mathlib
open Topology

variable {n : ℕ}

def ProductionSet.IsEfficient (Y : Set (Fin n → ℝ)) (y : Fin n → ℝ) : Prop :=
  y ∈ Y ∧ ¬∃ y' ∈ Y, y' ≠ y ∧ ∀ i, y i ≤ y' i

import Mathlib
open Topology

variable {n : ℕ}

/-- The ray generated by a vector `y` in a production set `Y` is the set of all positive scalar
    multiples of `y` that lie in `Y`. -/
def ray (Y : Set (Fin n → ℝ)) (y : Fin n → ℝ) : Set (Fin n → ℝ) :=
  {ybar ∈ Y | ∃ α : ℝ, α > 0 ∧ ybar = α • y}

